using Aspire.Hosting.Testing;
using Xunit;

namespace MyApp.Evaluation;

/// <summary>
/// Evaluation harness that starts the AppHost and runs evaluation scenarios
/// defined in evaluation.yml against the agentic application.
/// </summary>
public class EvaluationHarness : IAsyncLifetime
{
    private DistributedApplication? _app;

    public async Task InitializeAsync()
    {
        var builder = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        _app = await builder.BuildAsync();
        await _app.StartAsync();
    }

    [Fact]
    public async Task AppHost_StartsSuccessfully()
    {
        Assert.NotNull(_app);
        // Verify the app host is running and healthy
        await _app!.WaitForResources().WaitAsync(TimeSpan.FromSeconds(60));
    }

    [Fact]
    public async Task AppHost_RespondsToHealthCheck()
    {
        Assert.NotNull(_app);
        // Allow time for resources to become healthy
        await _app!.WaitForResources().WaitAsync(TimeSpan.FromSeconds(60));
    }

    public async Task DisposeAsync()
    {
        if (_app is not null)
        {
            await _app.StopAsync();
            await _app.DisposeAsync();
        }
    }
}

